/**
 * WordPress dependencies
 */
import { useEffect } from '@safe-wordpress/element';
import { _x } from '@safe-wordpress/i18n';

/**
 * External dependencies
 */
import introJs from 'intro.js';
import { usePluginSetting } from '@nab/data';
import { getValue, setValue } from '@nab/utils';
import type { Tour } from 'intro.js/src/packages/tour';
import type { TourStep } from 'intro.js/src/packages/tour/steps';

/**
 * Internal dependencies
 */
import './style.scss';
import type { TutorialStep } from '../types';

export function useWalkthroughEffect(
	screen: string,
	steps: ReadonlyArray< TutorialStep >
): false | ( () => void ) {
	const areAutoTutorialsEnabled = usePluginSetting(
		'areAutoTutorialsEnabled'
	);
	const shouldAutoRun =
		areAutoTutorialsEnabled &&
		!! steps.length &&
		shouldRunOnStartup( screen );

	useEffect( () => {
		if ( ! shouldAutoRun ) {
			return;
		}
		const timeout = setTimeout(
			() => void createTour( screen, steps ).start(),
			100
		);
		return () => clearTimeout( timeout );
	}, [ screen, shouldAutoRun, steps ] );

	return (
		!! steps.length && ( () => void createTour( screen, steps ).start() )
	);
}

// =======
// HELPERS
// =======

function createTour(
	screen: string,
	steps: ReadonlyArray< TutorialStep >
): Tour {
	const finalSteps = [
		...steps,
		{
			title: _x( 'Enjoy!', 'text', 'nelio-ab-testing' ),
			intro: _x(
				'That’s all! If you have any further questions or you want to view this guide again, click on “Help”.',
				'user',
				'nelio-ab-testing'
			),
			element: () =>
				document.querySelector( '.nab-contextual-help__toggle' ),
		} as TutorialStep,
	]
		.filter( ( s: TutorialStep ) => ! s?.active || s.active() )
		.map( tutorialStepToIntroStep );

	const newTour = introJs.tour().setOptions( {
		buttonClass: 'button button-secondary nab-walkthrough-button',
		disableInteraction: true,
		exitOnOverlayClick: false,
		overlayOpacity: 0.8,
		tooltipClass: 'nab-walkthrough-tooltip',

		prevLabel: _x( 'Prev', 'command', 'nelio-ab-testing' ),
		nextLabel: _x( 'Next', 'command', 'nelio-ab-testing' ),
		doneLabel: _x( 'Close', 'command', 'nelio-ab-testing' ),

		showBullets: false,
		showProgress: false,
		showStepNumbers: true,
		/* translators: Used in pagination, e.g. “2 of 6”. */
		stepNumbersOfLabel: _x( 'of', 'text (introjs)', 'nelio-ab-testing' ),

		steps: finalSteps,
	} );

	newTour.onStart( () => setValue( `is-guide-${ screen }-disabled`, true ) );

	return newTour;
}

function tutorialStepToIntroStep(
	step: TutorialStep,
	index: number
): Pick< TourStep, 'title' | 'intro' | 'element' | 'tooltipClass' > {
	const element = step.element?.();
	return {
		title: step.title,
		intro: step.intro,
		element: element || null,
		tooltipClass: `nab-walkthrough-step-${ index + 1 }`,
	};
}

function shouldRunOnStartup( screen: string ): boolean {
	return (
		! getValue( 'are-guides-disabled', false ) &&
		! getValue( `is-guide-${ screen }-disabled`, false )
	);
}
