/**
 * WordPress dependencies
 */
import {
	Button,
	DropdownMenu,
	Modal,
	Path,
	SelectControl,
	SVG,
	TextControl,
} from '@safe-wordpress/components';
import { useEffect, useState } from '@safe-wordpress/element';
import { _x, sprintf } from '@safe-wordpress/i18n';
import { addQueryArgs, getQueryArg } from '@safe-wordpress/url';

/**
 * External dependencies
 */
import { findIndex, noop } from 'lodash';
import { usePageAttribute, usePluginSetting } from '@nab/data';
import { getLetter } from '@nab/utils';
import type {
	Alternative,
	AlternativeId,
	Maybe,
	CssSelectorFinderState as State,
} from '@nab/types';

/**
 * Internal dependencies
 */
import './style.scss';

export type CssSelectorFinderProps = {
	readonly initialUrl: string;
	readonly initialMode: State[ 'mode' ];
	readonly initialValue: string;
	readonly alternatives: ReadonlyArray< Alternative >;
	readonly onClose?: () => void;
	readonly onAccept?: ( mode: State[ 'mode' ], val: string ) => void;
};

export const CssSelectorFinder = ( {
	initialUrl,
	initialMode,
	initialValue,
	...props
}: CssSelectorFinderProps ): JSX.Element => {
	const [ state, setState ] = useCssFinderState( initialMode, initialValue );

	const validationMessage = useValidationMessage( state );

	return (
		<Modal
			className="nab-css-selector-finder"
			title={
				(
					<Title
						initialUrl={ initialUrl }
						state={ state }
						setState={ ( v ) => v && setState( v ) }
						validationMessage={ validationMessage }
						{ ...props }
					/>
				 ) as unknown as string
			}
			onRequestClose={ noop }
			isDismissible={ false }
			style={ {
				width: '100%',
				height: '100%',
				padding: 0,
			} }
		>
			<iframe
				className="nab-css-selector-finder__iframe"
				title={ _x(
					'CSS Selector Finder',
					'text',
					'nelio-ab-testing'
				) }
				src={ addQueryArgs( state.initialUrl || initialUrl, {
					'nab-css-selector-finder': true,
				} ) }
				onLoad={ () => setState( state ) }
			></iframe>
		</Modal>
	);
};

type TitleProps = Omit<
	CssSelectorFinderProps,
	'initialValue' | 'initialMode'
> & {
	readonly state: State;
	readonly setState: ( s?: State ) => void;
	readonly validationMessage?: string;
};

const Title = ( {
	alternatives,
	initialUrl,
	state,
	setState,
	validationMessage,
	onClose = noop,
	onAccept = noop,
}: TitleProps ): JSX.Element => {
	const options = alternatives.map( ( { id }, i ) => ( {
		label: getLabel( i ),
		value: id,
	} ) );

	const { mode, alternative, value, interactionMode } = state;
	const isHovering = 'navigation' !== interactionMode;
	const placeholder = ( (): string => {
		switch ( mode ) {
			case 'id':
				return _x( 'Type an element ID…', 'user', 'nelio-ab-testing' );
			case 'class':
				return _x( 'Type a class name…', 'user', 'nelio-ab-testing' );
			case 'css':
				return isHovering
					? _x(
							'Click on an element or type a CSS selector…',
							'user',
							'nelio-ab-testing'
						)
					: _x( 'Type a CSS selector…', 'user', 'nelio-ab-testing' );
		}
	} )();

	const loadAlternative = ( id: AlternativeId ) => {
		const index = findIndex( options, { value: id } );
		setState( {
			...state,
			alternative: index,
			initialUrl: alternatives[ index ]?.links.preview,
		} );
	};

	const homeUrl = usePreviewHomeUrl( state.initialUrl || initialUrl );
	const loadHome = homeUrl
		? () =>
				setState( {
					...state,
					initialUrl: addQueryArgs( homeUrl, {
						'nab-css-selector-finder': true,
						'nab-home':
							'1' ===
							getQueryArg( state?.initialUrl ?? '', 'nab-home' )
								? 2
								: 1,
					} ),
				} )
		: undefined;

	const setValue = ( val: string ) =>
		setState( {
			...state,
			value: val,
		} );

	const cleanState = () => setState( undefined );

	return (
		<div className="nab-css-selector-finder__header">
			<div className="nab-css-selector-finder__header-left">
				<SelectControl
					options={ options }
					value={ options[ alternative ]?.value }
					onChange={ loadAlternative }
				/>
				{ !! loadHome && (
					<Button
						variant="primary"
						className="nab-css-selector-finder__action"
						onClick={ loadHome }
						icon="admin-home"
					/>
				) }
			</div>

			<div className="nab-css-selector-finder__header-center">
				<TextControl
					className="nab-css-selector-finder__value"
					placeholder={ placeholder }
					value={ value }
					onChange={ setValue }
					help={ validationMessage }
				/>
				{ mode === 'css' && (
					<DropdownMenu
						className="nab-css-selector-finder__interactivity-mode"
						icon={
							isHovering ? SingleInspectorIcon : NavigationIcon
						}
						label={
							isHovering
								? _x(
										'Select an element',
										'user',
										'nelio-ab-testing'
									)
								: _x(
										'Navigate your site',
										'user',
										'nelio-ab-testing'
									)
						}
						toggleProps={ { variant: 'primary' } }
						controls={ [
							{
								title: _x(
									'Navigate your site',
									'user',
									'nelio-ab-testing'
								),
								isActive: ! isHovering,
								icon: NavigationIcon,
								onClick: () =>
									setState( {
										...state,
										interactionMode: 'navigation',
									} ),
							},
							{
								title: _x(
									'Select an element',
									'user',
									'nelio-ab-testing'
								),
								isActive: isHovering,
								icon: SingleInspectorIcon,
								onClick: () =>
									setState( {
										...state,
										interactionMode: 'single-inspector',
									} ),
							},
						] }
					/>
				) }
			</div>

			<div className="nab-css-selector-finder__header-right">
				<Button
					variant="secondary"
					className="nab-css-selector-finder__action"
					onClick={ () => {
						onClose();
						cleanState();
					} }
				>
					{ _x( 'Cancel', 'command', 'nelio-ab-testing' ) }
				</Button>

				<Button
					variant="primary"
					className="nab-css-selector-finder__action"
					disabled={ ! value }
					onClick={ () => {
						onAccept( mode, value );
						onClose();
						cleanState();
					} }
				>
					{ _x( 'OK', 'command', 'nelio-ab-testing' ) }
				</Button>
			</div>
		</div>
	);
};

