/**
 * WordPress dependencies
 */
import apiFetch from '@safe-wordpress/api-fetch';
import {
	Button,
	Dashicon,
	ExternalLink,
	HStack,
	Popover,
	Spinner,
	TextControl,
} from '@safe-wordpress/components';
import { useSelect } from '@safe-wordpress/data';
import {
	createInterpolateElement,
	useCallback,
	useEffect,
	useState,
} from '@safe-wordpress/element';
import { _x } from '@safe-wordpress/i18n';
import { addQueryArgs } from '@safe-wordpress/url';

/**
 * External dependencies
 */
import clsx from 'clsx';
import { noop } from 'lodash';
import { store as NAB_ACCOUNT } from '@nab/account';
import { store as NAB_DATA } from '@nab/data';
import { formatNumber } from '@nab/i18n';
import { addFreeTracker, openNativeBrowserDialog } from '@nab/utils';

/**
 * Internal dependencies
 */
import './style.scss';

export type QuotaPurchaseActionProps = {
	readonly className?: string;
	readonly children?: string | JSX.Element | string[] | JSX.Element[];
	readonly variant: 'primary' | 'secondary' | 'link' | 'page-title-action';
};

type SessionResponse = {
	readonly sessionId?: string;
};

type State = {
	readonly status:
		| 'closed'
		| 'quota-selection'
		| 'creating-session'
		| 'awaiting-checkout'
		| 'done';
	readonly sessionId: string;
	readonly checkoutDialog: Window | null;
};

const VALID_MESSAGE_TYPES = [
	'nab/checkout-ready',
	'nab/purchase-completed',
] as const;
type SubscribeMessage = {
	readonly type: ( typeof VALID_MESSAGE_TYPES )[ number ];
};
const CHECKOUT_URL = 'https://neliosoftware.com/testing/subscribe/checkout/';
const CLOSED_STATE: State = {
	status: 'closed',
	sessionId: '',
	checkoutDialog: null,
};

export const QuotaPurchaseAction = ( {
	className,
	children,
	variant,
}: QuotaPurchaseActionProps ): JSX.Element | null => {
	const [ state, setState ] = usePurchaseQuotaState();
	const canPurchaseQuota = useCanPurchaseQuota();
	useMessageListenerEffect( state, setState );

	if ( ! canPurchaseQuota ) {
		return null;
	}

	if ( 'page-title-action' === variant ) {
		className = variant + ' ' + className;
	}

	const open = () => setState( { status: 'quota-selection' } );
	const close = () =>
		setState( { ...CLOSED_STATE, checkoutDialog: state.checkoutDialog } );

	return (
		<span>
			<Button
				className={ `nab-purchase-quota-action nab-purchase-quota-action--is-${ variant } ${ className }` }
				variant={
					'page-title-action' === variant ? 'secondary' : variant
				}
				onClick={ open }
			>
				{ children ??
					_x( 'Buy More Quota', 'command', 'nelio-ab-testing' ) }
			</Button>
			<QuotaPurchasePopover
				state={ state }
				setState={ setState }
				isPageTitleAction={ 'page-title-action' === variant }
				placement="bottom"
				onFocusOutside={ close }
				isOpen={
					'quota-selection' === state.status ||
					'creating-session' === state.status
				}
			/>
		</span>
	);
};

// ============
// HELPER VIEWS
// ============

type PopoverProps = {
	readonly isPageTitleAction: boolean;
	readonly isOpen: boolean;
	readonly placement: Popover.Props[ 'placement' ];
	readonly state: State;
	readonly setState: ReturnType< typeof usePurchaseQuotaState >[ 1 ];
	readonly onFocusOutside: () => void;
};

const QuotaPurchasePopover = ( props: PopoverProps ) =>
	props.isOpen ? <ActualQuotaPurchasePopover { ...props } /> : null;

const ActualQuotaPurchasePopover = ( {
	isPageTitleAction,
	placement,
	state,
	setState,
	onFocusOutside,
}: PopoverProps ): JSX.Element | null => {
	const [ quantity, setQuantity ] = useState( 1 );
	const product = useQuotaProduct();

	const purchaseQuota = useCallback( async () => {
		try {
			setState( { status: 'creating-session' } );
			const { sessionId } = await apiFetch< SessionResponse >( {
				path: '/nab/v1/subscription/purchase-session',
				method: 'POST',
				data: {
					cart: {
						lineItems: [
							{
								productPath: 'nab-extra-quota',
								quantity,
							},
						],
					},
				},
			} );
			setState( { status: 'awaiting-checkout', sessionId } );
			const dialog = openNativeBrowserDialog(
				addQueryArgs( CHECKOUT_URL, { session: sessionId } )
			);
			if ( dialog ) {
				setState( {
					status: 'awaiting-checkout',
					checkoutDialog: dialog,
				} );
			} else {
				setState( {
					status: 'closed',
				} );
			}
		} catch ( _ ) {
			setState( { status: 'closed' } );
		}
	}, [ quantity, setState ] );

	if ( ! product ) {
		return (
			<Popover
				className={ clsx(
					'nab-quota-purchase',
					'nab-quota-purchase--loading',
					{
						'nab-quota-purchase--is-page-title-action':
							isPageTitleAction,
					}
				) }
				focusOnMount={ true }
				noArrow={ false }
				placement={ placement }
				onFocusOutside={ onFocusOutside }
			>
				<Spinner />
			</Popover>
		);
	}

	const { pageviews, currency, price } = product;
	const value = pageviews * quantity;

	return (
		<Popover
			className={ clsx( 'nab-quota-purchase', {
				'nab-quota-purchase--is-page-title-action': isPageTitleAction,
			} ) }
			focusOnMount={ true }
			noArrow={ false }
			placement={ placement }
			onFocusOutside={ onFocusOutside }
		>
			<div className="nab-quota-purchase__container">
				<TextControl
					className="nab-quota-purchase__value"
					value={ formatNumber( value ) }
					onChange={ () => null }
					readOnly
				/>

				<HStack className="nab-quota-purchase__buttons">
					<Button
						variant="secondary"
						aria-disabled={ quantity === 1 }
						onClick={ () =>
							setQuantity( Math.max( quantity - 1, 1 ) )
						}
					>
						<Dashicon icon="minus" />
					</Button>
					<Button
						variant="secondary"
						onClick={ () => setQuantity( quantity + 1 ) }
					>
						<Dashicon icon="plus" />
					</Button>
				</HStack>
			</div>

			<div className="nab-quota-purchase__footer-container">
				<span className="nab-quota-purchase__total">
					{ _x( 'Total:', 'text', 'command' ) }
					<span className="nab-quota-purchase__total-value">
						{ formatPrice( price * quantity, currency ) }
					</span>
				</span>

				<Button
					variant="primary"
					className="nab-quota-purchase-form__button"
					onClick={
						'quota-selection' === state.status
							? purchaseQuota
							: noop
					}
					isBusy={ 'creating-session' === state.status }
				>
					{ 'creating-session' === state.status
						? _x( 'Please wait…', 'user', 'nelio-ab-testing' )
						: _x( 'Purchase', 'command', 'nelio-ab-testing' ) }
				</Button>
			</div>

			<p className="nab-quota-purchase__help">
				{ createInterpolateElement(
					_x(
						'Please notice the system may need a few moments to increase your quota after the purchase. Visit our <help>Knowledge Base</help> for more details.',
						'user',
						'nelio-ab-testing'
					),
					{
						help: (
							// @ts-expect-error children prop is set by createInterpolateComponent.
							<ExternalLink
								href={ addFreeTracker(
									'https://neliosoftware.com/testing/help/how-to-purchase-quota/'
								) }
							/>
						),
					}
				) }
			</p>
		</Popover>
	);
};

// =====
// HOOKS
// =====

const usePurchaseQuotaState = () => {
	const [ state, setFullState ] = useState< State >( CLOSED_STATE );

	const setState = ( newState: Partial< State > & Pick< State, 'status' > ) =>
		setFullState( ( prevState ) => ( {
			status: newState.status,
			sessionId: newState.sessionId ?? prevState.sessionId,
			checkoutDialog: newState.checkoutDialog ?? prevState.checkoutDialog,
		} ) );

	return [ state, setState ] as const;
};
const useQuotaProduct = () => {
	const product = useSelect(
		( select ) =>
			select( NAB_DATA )
				.getProducts()
				.find( ( p ) => p.id === 'nab-extra-quota' ),
		[]
	);
	const currency = useSelect(
		( select ) => select( NAB_DATA ).getCurrency() || 'USD',
		[]
	);

	if ( ! product ) {
		return;
	}

	const price = product.price[ currency ] || product.price.USD || 0;
	const pageviews =
		Number.parseInt( product?.attributes?.pageviews || '' ) || 0;

	return { currency, price, pageviews };
};

const useCanPurchaseQuota = () =>
	useSelect(
		( select ) =>
			select( NAB_DATA ).hasCapability( 'manage_nab_account' ) &&
			! select( NAB_DATA ).getPluginSetting(
				'areSubscriptionControlsDisabled'
			) &&
			select( NAB_DATA ).isSubscribedTo( 'basic', 'or-above' ) &&
			! select( NAB_DATA ).isSubscribedTo( 'enterprise' ) &&
			'canceled' !== select( NAB_ACCOUNT ).getState() &&
			'free' !== select( NAB_ACCOUNT ).getMode() &&
			'invitation' !== select( NAB_ACCOUNT ).getMode(),
		[]
	);

const useMessageListenerEffect = (
	state: State,
	setState: ReturnType< typeof usePurchaseQuotaState >[ 1 ]
) => {
	useEffect( () => {
		const onMessage = ( event: MessageEvent ): true => {
			if ( event.source !== state.checkoutDialog ) {
				return true;
			}

			if ( event.origin !== 'https://neliosoftware.com' ) {
				return true;
			}

			const message = getSubscribeMessage( event.data );
			if ( ! message ) {
				return true;
			}

			switch ( message.type ) {
				case 'nab/checkout-ready':
					return true;

				case 'nab/purchase-completed':
					state.checkoutDialog?.close();
					setState( { status: 'done', checkoutDialog: null } );
					return true;
			}
		};
		window.addEventListener( 'message', onMessage );

		const onNativeBrowserDialogClosed = () => {
			if ( 'closed' === state.status ) {
				return;
			}
			if ( 'done' !== state.status ) {
				setState( { status: 'closed' } );
			}
		};
		window.addEventListener(
			'nab/native-browser-dialog-closed',
			onNativeBrowserDialogClosed
		);
		return () => {
			window.removeEventListener( 'message', onMessage );
			window.removeEventListener(
				'nab/native-browser-dialog-closed',
				onNativeBrowserDialogClosed
			);
		};
	}, [ state, setState ] );
};
// =======
// HELPERS
// =======

const formatPrice = ( price: number, currency: string ): string => {
	switch ( currency ) {
		case 'EUR':
			return `${ formatNumber( price ) }€`;
		case 'USD':
		default:
			return `$${ formatNumber( price ) }`;
	}
};

const getSubscribeMessage = ( data: unknown ): SubscribeMessage | false => {
	if (
		! data ||
		'object' !== typeof data ||
		! ( 'type' in data ) ||
		'string' !== typeof data.type
	) {
		return false;
	}

	const message = data as {
		readonly type: string;
	};

	if (
		! VALID_MESSAGE_TYPES.includes(
			message.type as SubscribeMessage[ 'type' ]
		)
	) {
		return false;
	}

	return {
		type: message.type as SubscribeMessage[ 'type' ],
	};
};
