type IconProps = SVGProps< SVGSVGElement >;

export const SuggestionIcon = ( {
	category,
	className,
	...props
}: IconProps & { readonly category: TestSuggestionCategory } ): JSX.Element => {
	const Icon = TEST_SUGGESTION_ICONS[ category ];
	return (
		<div
			className={ clsx( className, [
				'nab-experiment-suggestion-icon',
				`nab-experiment-suggestion-icon--${ category }`,
			] ) }
		>
			<Icon { ...props } />
		</div>
	);
};

